import { Tooltip as BaseTooltip } from "@base-ui/react/tooltip";
import { Slot } from "@radix-ui/react-slot";
import {
  createContext,
  useCallback,
  type MutableRefObject,
  type ButtonHTMLAttributes,
  type FocusEvent,
  forwardRef,
  type HTMLAttributes,
  type PointerEvent,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { useOverlayRoot, useOverlayDismiss } from "@/components/ui/overlay-root";
import { cn } from "@/lib/cn";
import { canAnimate, motionEasing, readMotion } from "@/lib/motion";

/**
 * Tooltips are warm together: once one has opened, its neighbours open at
 * once until the pointer has rested away from every tooltip for a moment.
 * Moving along a toolbar then reads each label without waiting each time.
 */
type Warmth = {
  open: number;
  warm: boolean;
  cooling: ReturnType<typeof setTimeout> | undefined;
};
const warmth: Warmth = { open: 0, warm: false, cooling: undefined };
/** How long the group stays warm after the last tooltip closes. */
const coolingMs = 600;

/** Supported TooltipSide values. */
export type TooltipSide = "bottom" | "left" | "right" | "top";

type TooltipContextValue = {
  /** The tooltip opened while its group was warm: it swaps in, it doesn't arrive. */
  arrivedWarm: boolean;
  cancelClose: () => void;
  contentId: string;
  open: boolean;
  scheduleClose: () => void;
  scheduleOpen: () => void;
  side: TooltipSide;
  trigger: MutableRefObject<HTMLButtonElement | null>;
};

const TooltipContext = createContext<null | TooltipContextValue>(null);

/** Props accepted by Tooltip. */
export type TooltipProps = {
  children: ReactNode;
  defaultOpen?: boolean;
  delayDuration?: number;
  /** Called after the tooltip open state changes. */
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
  side?: TooltipSide;
} & Omit<HTMLAttributes<HTMLSpanElement>, "children">;

function useTooltipContext(): TooltipContextValue {
  const context = useContext(TooltipContext);
  if (!context) throw new Error("Tooltip parts must be used inside <Tooltip>");
  return context;
}

/** A tooltip controller with explicit controlled or uncontrolled open state. */
export const Tooltip = forwardRef<HTMLSpanElement, TooltipProps>(
  function Tooltip(
    {
      children,
      className,
      defaultOpen = false,
      delayDuration = 300,
      onOpenChange,
      open: controlledOpen,
      side = "top",
      ...props
    },
    forwardedRef,
  ) {
    const trigger = useRef<HTMLButtonElement | null>(null);
    const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
    const [arrivedWarm, setArrivedWarm] = useState(false);
    const open = controlledOpen ?? uncontrolledOpen;
    // Count this tooltip toward its group's warmth while it is open.
    useEffect(() => {
      if (!open) return;
      warmth.open += 1;
      warmth.warm = true;
      clearTimeout(warmth.cooling);
      return () => {
        warmth.open -= 1;
        if (warmth.open > 0) return;
        warmth.cooling = setTimeout(() => {
          warmth.warm = false;
        }, coolingMs);
      };
    }, [open]);
    const contentId = `${useId()}-content`;
    const timer = useRef<null | ReturnType<typeof setTimeout>>(null);
    const clearTimer = () => {
      if (timer.current !== null) {
        clearTimeout(timer.current);
        timer.current = null;
      }
    };
    const setOpen = (next: boolean) => {
      clearTimer();
      if (controlledOpen === undefined) setUncontrolledOpen(next);
      onOpenChange?.(next);
    };
    useOverlayDismiss(() => {
      setOpen(false);
    });
    const scheduleOpen = () => {
      clearTimer();
      if (open) return;
      const warm = warmth.warm;
      timer.current = setTimeout(
        () => {
          setArrivedWarm(warm);
          setOpen(true);
        },
        warm ? 0 : Math.max(0, delayDuration),
      );
    };
    const scheduleClose = () => {
      clearTimer();
      if (!open) return;
      timer.current = setTimeout(() => {
        setOpen(false);
      }, 0);
    };
    useEffect(() => clearTimer, []);
    return (
      <TooltipContext.Provider
        value={{
          arrivedWarm,
          cancelClose: clearTimer,
          contentId,
          open,
          scheduleClose,
          scheduleOpen,
          side,
          trigger,
        }}
      >
        <BaseTooltip.Root open={open} onOpenChange={setOpen}>
          <span
            {...props}
            className={cn("relative inline-flex", className)}
            ref={forwardedRef}
          >
            {children}
          </span>
        </BaseTooltip.Root>
      </TooltipContext.Provider>
    );
  },
);

/** Props accepted by TooltipTrigger. */
export type TooltipTriggerProps = {
  asChild?: boolean;
  children?: ReactNode;
} & ButtonHTMLAttributes<HTMLButtonElement>;

/** The trigger control for a Tooltip. */
export const TooltipTrigger = forwardRef<
  HTMLButtonElement,
  TooltipTriggerProps
>(function TooltipTrigger(
  {
    asChild = false,
    children,
    className,
    onBlur,
    onFocus,
    onPointerEnter,
    onPointerLeave,
    ...props
  },
  forwardedRef,
) {
  const tooltip = useTooltipContext();
  const attach = useCallback(
    (node: HTMLButtonElement | null) => {
      tooltip.trigger.current = node;
    },
    [tooltip.trigger],
  );
  useImperativeHandle<HTMLButtonElement | null, HTMLButtonElement | null>(
    forwardedRef,
    () => tooltip.trigger.current,
  );
  const { "aria-describedby": callerDescribedBy, ...nativeProps } = props;
  const triggerProps = {
    ...nativeProps,
    "aria-describedby":
      [callerDescribedBy, tooltip.open ? tooltip.contentId : undefined]
        .filter(Boolean)
        .join(" ") || undefined,
    "data-state": tooltip.open ? "open" : "closed",
    onBlur: (event: FocusEvent<HTMLButtonElement>) => {
      onBlur?.(event);
      if (!event.defaultPrevented) tooltip.scheduleClose();
    },
    onFocus: (event: FocusEvent<HTMLButtonElement>) => {
      onFocus?.(event);
      if (!event.defaultPrevented) tooltip.scheduleOpen();
    },
    onPointerEnter: (event: PointerEvent<HTMLButtonElement>) => {
      onPointerEnter?.(event);
      if (!event.defaultPrevented) tooltip.scheduleOpen();
    },
    onPointerLeave: (event: PointerEvent<HTMLButtonElement>) => {
      onPointerLeave?.(event);
      if (!event.defaultPrevented) tooltip.scheduleClose();
    },
  };
  if (asChild) {
    return (
      <Slot {...triggerProps} className={cn(className)} ref={attach}>
        {children}
      </Slot>
    );
  }
  return (
    <button
      {...triggerProps}
      className={cn("btn", className)}
      ref={attach}
      type={props.type ?? "button"}
    >
      {children}
    </button>
  );
});

/** Props accepted by TooltipContent. */
export type TooltipContentProps = {
  children: ReactNode;
} & HTMLAttributes<HTMLDivElement>;

/** The positioned content region for a Tooltip. */
export const TooltipContent = forwardRef<HTMLDivElement, TooltipContentProps>(
  function TooltipContent(
    { children, className, onPointerEnter, onPointerLeave, ...props },
    ref,
  ) {
    const tooltip = useTooltipContext();
    const root = useOverlayRoot("tooltip");
    const [node, setNode] = useState<HTMLDivElement | null>(null);
    useImperativeHandle<HTMLDivElement | null, HTMLDivElement | null>(
      ref,
      () => node,
      [node],
    );
    // A cold tooltip arrives from its trigger; a warm one simply swaps in.
    useLayoutEffect(() => {
      const element = node;
      if (!tooltip.open || !element || !canAnimate(element)) return;
      const motion = readMotion(element);
      const travel = tooltip.arrivedWarm ? 0 : motion.distance;
      const offset = {
        bottom: `0 ${String(-travel)}px`,
        left: `${String(travel)}px 0`,
        right: `${String(-travel)}px 0`,
        top: `0 ${String(travel)}px`,
      }[tooltip.side];
      const arrival = element.animate(
        [
          { opacity: 0, translate: offset },
          { opacity: 1, translate: "0 0" },
        ],
        {
          duration: tooltip.arrivedWarm ? motion.fast : motion.normal,
          easing: motionEasing(motion, motion.ease),
          composite: "add",
        },
      );
      return () => {
        arrival.cancel();
      };
    }, [node, tooltip.open, tooltip.arrivedWarm, tooltip.side]);
    if (!tooltip.open || !root) return null;
    return (
      <BaseTooltip.Portal container={root}>
        <BaseTooltip.Positioner
          anchor={tooltip.trigger}
          side={tooltip.side}
          sideOffset={8}
          collisionPadding={8}
          collisionBoundary={root === document.body ? undefined : root}
          className="pointer-events-auto z-(--stipe-layer-tooltip)"
        >
          <BaseTooltip.Popup
            {...props}
            aria-live="polite"
            className={cn(
              "pointer-events-auto max-w-(--container-xs) rounded-box bg-base-content px-md py-sm text-xs text-base-100 shadow-lg",
              className,
            )}
            id={tooltip.contentId}
            onPointerEnter={(event) => {
              onPointerEnter?.(event);
              if (!event.defaultPrevented) tooltip.cancelClose();
            }}
            onPointerLeave={(event) => {
              onPointerLeave?.(event);
              if (!event.defaultPrevented) tooltip.scheduleClose();
            }}
            ref={setNode}
            role="tooltip"
          >
            {children}
          </BaseTooltip.Popup>
        </BaseTooltip.Positioner>
      </BaseTooltip.Portal>
    );
  },
);

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

import {
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type RefObject,
} from "react";

/** Resolved, element-scoped motion. Times are milliseconds and distances pixels. */
export type Motion = Readonly<{
  reduced: boolean;
  squish: number;
  fast: number;
  normal: number;
  slow: number;
  springDuration: number;
  bounce: number;
  stretch: number;
  distance: number;
  stagger: number;
  blur: number;
  shake: number;
  steps: number;
  fuse: number;
  pressDepth: number;
  pressScale: number;
  ease: string;
  easeExit: string;
}>;

const defaults: Motion = Object.freeze({
  reduced: false,
  squish: 90,
  fast: 120,
  normal: 180,
  slow: 280,
  springDuration: 320,
  bounce: 0.3,
  stretch: 0.28,
  distance: 4,
  stagger: 24,
  blur: 0,
  shake: 3,
  steps: 0,
  fuse: 1,
  pressDepth: 0.5,
  pressScale: 1,
  ease: "cubic-bezier(0.2, 0, 0, 1)",
  easeExit: "cubic-bezier(0.4, 0, 1, 1)",
});

const preference = "(prefers-reduced-motion: reduce)";

/** Read at an event boundary; no root-theme lookup, so nested tokens win. */
export function readMotion(element: Element): Motion {
  const view = element.ownerDocument.defaultView;
  if (!view) return defaults;
  const style = view.getComputedStyle(element);
  const number = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  };
  const time = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    return (
      number(name, fallback) *
      (value.endsWith("s") && !value.endsWith("ms") ? 1000 : 1)
    );
  };
  const browser: Partial<Pick<Window, "matchMedia">> = view;
  const reduced = browser.matchMedia?.(preference).matches ?? false;
  const duration = (name: string, fallback: number) =>
    reduced ? 120 : time(`--stipe-motion-${name}`, fallback);
  const amount = (name: string, fallback: number) =>
    reduced ? 0 : number(`--stipe-motion-${name}`, fallback);
  return {
    reduced,
    squish: duration("squish", defaults.squish),
    fast: duration("fast", defaults.fast),
    normal: duration("normal", defaults.normal),
    slow: duration("slow", defaults.slow),
    springDuration: duration("spring-duration", defaults.springDuration),
    bounce: Math.min(1, amount("bounce", defaults.bounce)),
    stretch: amount("stretch", defaults.stretch),
    distance: amount("distance", defaults.distance),
    stagger: reduced ? 0 : time("--stipe-motion-stagger", defaults.stagger),
    blur: amount("blur", defaults.blur),
    shake: amount("shake", defaults.shake),
    steps: Math.floor(amount("steps", defaults.steps)),
    fuse: number("--stipe-motion-fuse", defaults.fuse),
    pressDepth: reduced
      ? 0
      : number("--stipe-press-depth", defaults.pressDepth),
    pressScale: reduced
      ? 1
      : number("--stipe-press-scale", defaults.pressScale),
    ease: style.getPropertyValue("--stipe-motion-ease").trim() || defaults.ease,
    easeExit:
      style.getPropertyValue("--stipe-motion-ease-exit").trim() ||
      defaults.easeExit,
  };
}

/** Live motion tokens for a mounted ref, including nested theme and OS changes. */
export function useMotion(ref: RefObject<Element | null>): Motion {
  const [motion, setMotion] = useState<Motion>(() => ({
    ...defaults,
    reduced: true,
  }));
  useLayoutEffect(() => {
    const element = ref.current;
    const view = element?.ownerDocument.defaultView;
    if (!element || !view) return;
    const update = () => {
      const next = readMotion(element);
      setMotion((previous) =>
        JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
      );
    };
    update();
    const observer = new view.MutationObserver(update);
    // Observe ancestors only: animation writes to descendants must not trigger reads.
    for (
      let parent: Element | null = element;
      parent;
      parent = parent.parentElement
    ) {
      observer.observe(parent, {
        attributes: true,
        attributeFilter: ["data-theme", "class", "style"],
      });
    }
    const browser: Partial<Pick<Window, "matchMedia">> = view;
    const media = browser.matchMedia?.(preference);
    media?.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media?.removeEventListener("change", update);
    };
  }, [ref]);
  return motion;
}

/** Today's feel: the defaults that components' authored timings are written against. */
export const motionDefaults: Motion = defaults;

/**
 * Scale one of a component's authored durations by the theme's tempo
 * (`--stipe-motion-normal` against its 180ms default). Today's themes return
 * the authored value unchanged; reduced motion returns 0 (nothing travels).
 */
export function motionTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round((authored * motion.normal) / defaults.normal);
}

/**
 * Scale one of a component's authored spring bounces by the theme's bounce
 * (`--stipe-motion-bounce` against its 0.3 default), so a lively control stays
 * livelier than a calm one inside every theme. A 0 theme is critically damped.
 */
export function motionBounce(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  const scaled = (authored * motion.bounce) / defaults.bounce;
  return Math.min(0.9, Math.max(0, scaled));
}

/** Scale an authored spring settle time by `--stipe-motion-spring-duration`. */
export function motionSpringTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round(
    (authored * motion.springDuration) / defaults.springDuration,
  );
}

/** A CSS easing for a Web Animation, stepped when the theme asks for it. */
export function motionEasing(motion: Motion, ease: string): string {
  return motion.steps > 0 ? `steps(${String(motion.steps)}, end)` : ease;
}

/** Whether the element can run Web Animations (not in jsdom or old engines). */
export function canAnimate(element: Element): boolean {
  return "animate" in element;
}

const globalWindow: Partial<Pick<Window, "matchMedia">> = globalThis;

function prefersReducedMotion(): boolean {
  return globalWindow.matchMedia?.(preference).matches ?? false;
}

function subscribeReducedMotion(update: () => void) {
  const media = globalWindow.matchMedia?.(preference);
  media?.addEventListener("change", update);
  return () => {
    media?.removeEventListener("change", update);
  };
}

/** Server renders assume reduced motion, so hydration never starts mid-move. */
function serverReducedMotion() {
  return true;
}

/**
 * The live reduced-motion preference alone, for controls that only need to
 * know whether to move (their timing comes from `readMotion` when they do).
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    prefersReducedMotion,
    serverReducedMotion,
  );
}

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  type ReactNode,
} from "react";

/** Semantic destinations; the host owns their paint order and positioning. */
export type OverlayLayer = "popover" | "dialog" | "toast" | "tooltip";
/** Host portal roots; null keeps an overlay waiting until its layer mounts. */
export type OverlayContainers = Readonly<
  Record<OverlayLayer, HTMLElement | null>
>;

const DismissContext = createContext<
  ((listener: () => void) => () => void) | undefined
>(undefined);

const Context = createContext<OverlayContainers | null>(null);

/** Supply shell portal roots without teaching Caps about the shell's layout. */
export function OverlayRoot({
  containers,
  children,
  subscribeDismiss,
}: {
  containers: OverlayContainers;
  children?: ReactNode;
  /** Subscribe to the host losing focus to a child surface or another window. */
  subscribeDismiss?: (listener: () => void) => () => void;
}) {
  return (
    <Context.Provider value={containers}>
      <DismissContext.Provider value={subscribeDismiss}>
        {children}
      </DismissContext.Provider>
    </Context.Provider>
  );
}

/** Wait for a provided root; standalone overlays use the current document body. */
export function useOverlayRoot(layer: OverlayLayer): HTMLElement | null {
  const containers = useContext(Context);
  if (containers !== null) return containers[layer];
  return Object.hasOwn(globalThis, "document") ? document.body : null;
}

/** Retire a transient overlay when its owning host requests light dismissal. */
export function useOverlayDismiss(dismiss: () => void): void {
  const subscribe = useContext(DismissContext);
  const callback = useRef(dismiss);
  callback.current = dismiss;
  useEffect(
    () =>
      subscribe?.(() => {
        callback.current();
      }),
    [subscribe],
  );
}
